WITH flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) > INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT id, device_code, reading_ts, status_bits, is_new_burst, session_id FROM islands
